sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_IsValidScope(strScope,vExpected)
	{
		function TestCase_IsValidScope_CheckResult(vInput,vExpected,vResult)
		{
			return (vExpected == vResult);
		}
		
		test.TestCase(
			'Function IsValidScope()',
			IsValidScope,
			{
				'strScope': strScope
			},
			vExpected,
			TestCase_IsValidScope_CheckResult);
	}
		
	TestCase_IsValidScope(null,false);


	TestCase_IsValidScope('',false);
	TestCase_IsValidScope(' ',false);
	TestCase_IsValidScope('A',false);
	TestCase_IsValidScope('a',false);
	TestCase_IsValidScope('x_',false);
	TestCase_IsValidScope('DevTools',false);
	TestCase_IsValidScope('x_34567890123456789',false);
	TestCase_IsValidScope('x_snc_devtools ',false);
	TestCase_IsValidScope(' x_snc_devtools',false);
	TestCase_IsValidScope(' x_snc_devtools ',false);
	TestCase_IsValidScope('now-condition-builder',false);
	TestCase_IsValidScope('now_condition_builder',false);

	
	
	TestCase_IsValidScope('x_snc_devtools',true);
	TestCase_IsValidScope('x_3456789012345678',true);
	TestCase_IsValidScope('sn-help-panel',true);
	TestCase_IsValidScope('now-condition-buil',true);
	TestCase_IsValidScope('now_condition_buil',true);


	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
